-- Resources content for Sourcework's paragraph-sized transcript lines and play-from-a-word
-- (CLAUDE.md, "Resources stay in step with the code"). Content only; no schema. The prefix continues
-- the sequence past 20261105120000; see 20261103120000's header on why the prefix is a sequence
-- number, not a date.
--
-- What changed for a reader: a speaker's long turn is cut into lines of about half a minute, each
-- with its own time, in new transcripts and (20261105120000) in existing ones; Copy transcript and
-- Download .txt carry those times; selecting a word plays from it.

select private.rc_release_guide(
  p_slug => 'sourcework-transcript-and-excerpts',
  p_tool_key => 'transcription',
  p_title => 'Working with the transcript and creating excerpts',
  p_summary => 'Find your way in a transcript, name speakers, and save a stretch of it as an excerpt.',
  p_screen_keys => array['sourcework.source'],
  p_sort_order => 15,
  p_version_note => 'Transcript lines are about half a minute long, each with its time, and a word plays from itself',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A recording opens as its own screen: the player, the transcript and, beside it, a panel of this source's excerpts. Excerpts are short clips saved for reuse. On a phone the same screen is three tabs, "},{"type":"text","text":"Transcript","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Speakers","marks":[{"type":"bold"}]},{"type":"text","text":", with the player docked at the bottom."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find your way"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find in this transcript","marks":[{"type":"bold"}]},{"type":"text","text":" looks for a word or phrase from two characters on. Matching words are highlighted. Select the arrows, or press Enter, to step through the matches."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each line begins with the time it starts. A long answer is cut into lines of about half a minute, at the end of a sentence, so there is always a time to point someone to — “what she said at 14:20.” Transcripts made earlier have been cut the same way. Select a word to play from it; on a word that is part of an excerpt, that also opens the excerpt. Selecting a stretch of text, to make an excerpt, still works as before."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The marks under the progress bar show where your excerpts are; select one to open it. With many excerpts the marks merge into a shaded strip, and darker means more excerpts there. Select a stretch of the strip to zoom the progress bar in until the excerpts separate into their own marks, and select "},{"type":"text","text":"Show the whole recording","marks":[{"type":"bold"}]},{"type":"text","text":" to zoom back out."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The player steps back and forward five seconds, changes speed, and follows the transcript as it plays; "},{"type":"text","text":"Jump to playhead","marks":[{"type":"bold"}]},{"type":"text","text":" scrolls back to the line being played. Space plays and pauses, and the "},{"type":"text","text":"?","marks":[{"type":"bold"}]},{"type":"text","text":" button lists the other keyboard shortcuts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Speakers","marks":[{"type":"bold"}]},{"type":"text","text":" button names the speakers, with the first few names after it. It opens a list ordered by who spoke most. Type a name to rename a speaker, select "},{"type":"text","text":"Hear an example","marks":[{"type":"bold"}]},{"type":"text","text":", or tick "},{"type":"text","text":"Interviewer","marks":[{"type":"bold"}]},{"type":"text","text":" beside the person asking the questions, so Analyze leaves their words out. "},{"type":"text","text":"Add","marks":[{"type":"bold"}]},{"type":"text","text":" at the bottom adds a speaker the transcript missed. From seven speakers a find box and an "},{"type":"text","text":"Unnamed only","marks":[{"type":"bold"}]},{"type":"text","text":" switch appear."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the transcript split one person into two voices, select "},{"type":"text","text":"Merge…","marks":[{"type":"bold"}]},{"type":"text","text":" on the extra speaker and choose who it really was. All of its lines move to that speaker."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a line"}]},{"type":"paragraph","content":[{"type":"text","text":"Select the ⋮ at the end of any line for "},{"type":"text","text":"Edit text","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Make an excerpt from this line","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Change speaker…","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Merge with the next line","marks":[{"type":"bold"}]},{"type":"text","text":". Double-clicking the text, or pressing E on the current line, also starts an edit, and while editing you can split the line at the cursor. Choosing "},{"type":"text","text":"＋ New speaker…","marks":[{"type":"bold"}]},{"type":"text","text":" when changing a line's speaker names someone new. "},{"type":"text","text":"Copy transcript","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Download .txt","marks":[{"type":"bold"}]},{"type":"text","text":", above the transcript, take the whole text with you, with the time at the start of each line."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a source's details"}]},{"type":"paragraph","content":[{"type":"text","text":"Select the ⋮ beside the source's title and choose "},{"type":"text","text":"Edit details","marks":[{"type":"bold"}]},{"type":"text","text":". A card opens with the title and, for a recording, the date it was recorded. Select "},{"type":"text","text":"Save","marks":[{"type":"bold"}]},{"type":"text","text":" to keep the change; the source's search entries update with it. A PDF has a title only. The same menu has "},{"type":"text","text":"Rebuild search index","marks":[{"type":"bold"}]},{"type":"text","text":", for a source transcribed before search existed or after a round of corrections, and the two ways out: "},{"type":"text","text":"Remove from this project…","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Delete source…","marks":[{"type":"bold"}]},{"type":"text","text":", each saying what it does before you confirm."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Create an excerpt"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Drag to select the stretch of text you want. On a phone, touch and hold a word, then drag."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"New excerpt","marks":[{"type":"bold"}]},{"type":"text","text":" bar opens at the bottom of the transcript with a title already filled in, and the time range beside it. The title starts as the first words you selected and, a moment later, is replaced by a short description of what the speaker says, if you haven't started typing. When you save, the excerpt is named in full: the project, then who is speaking, then your title, such as Hurricane Isaias_Chip Simmons_Second fatality from generator fumes. That is also the name of the file you download."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Change the title if you like, then press Enter or select "},{"type":"text","text":"Save excerpt","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"Preview","marks":[{"type":"bold"}]},{"type":"text","text":" plays the exact range; Esc cancels."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Working with excerpts"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The panel lists this source's excerpts. "},{"type":"text","text":"In order","marks":[{"type":"bold"}]},{"type":"text","text":" follows the recording and "},{"type":"text","text":"Newest","marks":[{"type":"bold"}]},{"type":"text","text":" puts the latest first. From nine excerpts a filter box appears, and twenty show at a time with "},{"type":"text","text":"Show more","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The round "},{"type":"text","text":"play button","marks":[{"type":"bold"}]},{"type":"text","text":" on a card plays that excerpt. While it plays the button turns into a pause button, so you can stop it from the card without going to the player. Playing another excerpt switches to that one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trim","marks":[{"type":"bold"}]},{"type":"text","text":" shows the clip's words. Tap a word to move the start or end there, or nudge them with the −250, −50, +50 and +250 buttons. "},{"type":"text","text":"Play as cut","marks":[{"type":"bold"}]},{"type":"text","text":" plays the result, and "},{"type":"text","text":"Done trimming","marks":[{"type":"bold"}]},{"type":"text","text":" closes it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Export WAV","marks":[{"type":"bold"}]},{"type":"text","text":" renders the clip to its own audio file; "},{"type":"text","text":"Download","marks":[{"type":"bold"}]},{"type":"text","text":" appears when it is ready, and the button then reads "},{"type":"text","text":"Re-export","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"Show in transcript","marks":[{"type":"bold"}]},{"type":"text","text":" scrolls to the clip's words."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Level","marks":[{"type":"bold"}]},{"type":"text","text":" line on a card shows the volume change applied to that excerpt, such as +4.2 dB. Every excerpt is measured when you create or trim it, then played and exported at a fixed level of -18 LUFS, the level the team preps actualities at in Audition, followed by a hard limiter that holds peaks at -6 dBFS. One actuality no longer comes in much hotter or quieter than the last. The level is one volume setting for the whole excerpt, so a speaker who drops to a whisper stays that far below their own normal voice; only the peaks are limited. Select "},{"type":"text","text":"Original level","marks":[{"type":"bold"}]},{"type":"text","text":" to play and export an excerpt as recorded, for example when the quiet is the point, and "},{"type":"text","text":"Even out","marks":[{"type":"bold"}]},{"type":"text","text":" to go back. A card that says "},{"type":"text","text":"measuring…","marks":[{"type":"bold"}]},{"type":"text","text":" is still being measured and updates by itself in a few seconds. If it says the excerpt couldn't be measured, it plays and exports as recorded."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Export excerpts (zip)","marks":[{"type":"bold"}]},{"type":"text","text":", in the Excerpts section of the project's Notebook, exports every excerpt in the project at once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select a card's title to rename it. "},{"type":"text","text":"Delete","marks":[{"type":"bold"}]},{"type":"text","text":" asks you to confirm."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"When the source is in a project"}]},{"type":"paragraph","content":[{"type":"text","text":"Opened from a project, the panel has a switch between "},{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Data points","marks":[{"type":"bold"}]},{"type":"text","text":": the findings and clips Analyze proposed for this source, underlined in the transcript where they are. See "},{"type":"text","text":"Analyzing a source","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-research"}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A PDF source works the same way, but you select a stretch of the extracted text instead of a time range. Its screen has "},{"type":"text","text":"Document","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Text","marks":[{"type":"bold"}]},{"type":"text","text":" views and a search box for the document."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trimming a clip after it has been exported makes that export stale. Re-export before you rely on the download."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Line menus and the speaker list work on a tablet or phone too: nothing waits on hovering. Tapping an excerpt's words on a phone opens it in a sheet; see "},{"type":"text","text":"Play, trim and manage an excerpt on a phone","marks":[{"type":"link","attrs":{"href":"/resources/tools/transcription/sourcework-excerpt-sheet-on-a-phone"}}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Level is never applied to the recording itself, only to playback and to exports. Very quiet field tape can need a boost of 35 to 45 dB. Past 20 dB the card notes that the boost raises the background noise along with the voice. If a clip is stereo with the voice in one channel only, the voice is played and exported on both sides. Re-export after changing an excerpt's level, since an earlier export keeps the level it was made at."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-29-sourcework-transcript-paragraphs',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-29',
  p_title => 'Sourcework transcripts have a time for every half minute',
  p_guide_slugs => array['sourcework-transcript-and-excerpts'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Transcripts are easier to read and to cite. A long answer from one speaker used to be a single block with one time at the top; it is now cut into lines of about half a minute at the end of a sentence, each starting with its own time. Transcripts that were already made have been cut the same way, apart from lines someone has edited. Copy transcript and Download .txt carry the same times. Selecting a word in the transcript now plays the recording from that word."}]}]}$body$
);
